import{createGame,build,building,actionCost,salvageValue,serviceGolems,golemMaxHP,crewServiceCost,crewStatus,repairBell,levelCap,MAX_LEVEL,BUILDINGS,MOBS,LANES,TOTAL_NIGHTS,raidInfo,defenseCount,startNight,step,drainEvents,setDestination,focusMob,volley,checkpoint,restore,retryDawn}from'./core.mjs';
import{VillageScene}from'./scene.js';
import{VillageAudio}from'./audio.js';
import{unitServiceCost}from'./golems.mjs';
import{headData}from'./models.js';
import{DISTRICTS,SITES,raidDetails}from'./campaign.mjs';
import{placeMarkers}from'./markers.mjs';
const $=id=>document.getElementById(id),QA=new URLSearchParams(location.search).get('qa')==='1',QA_IDLE=QA&&new URLSearchParams(location.search).get('pilot')==='idle',KEY='village-last-stand-v2'+(QA?'-qa':'');
let saved;try{saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.checkpoint?.version===2&&!localStorage.getItem(KEY+'-pre-v0.3.0'))localStorage.setItem(KEY+'-pre-v0.3.0',JSON.stringify(saved));}catch{}
if(!saved){try{const old=JSON.parse(localStorage.getItem('village-last-stand-v1'+(QA?'-qa':''))||'null');if(old)saved={sound:old.sound,reduced:old.reduced,started:false};}catch{}}
const store={sound:true,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,best:0,started:false,...saved};
let run=restore(store.checkpoint)||createGame(seed()),scene,modal=null,selected='northwatch',resultShown=false,last=performance.now(),saveClock=0,uiClock=0,toastTime=0,pointerInput={x:0,z:0};let qaSpeed=1,qaAuto=false,qaModule=null,qaPilotState=null,qaFrames=0,qaWall=0,qaBudget=0,qaHold=false,qaBreakOnLoss=false,raidUIKey='';const keys=new Set(),audio=new VillageAudio();audio.enabled=store.sound;
function seed(){const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0];}
function persist(){store.checkpoint=['won','lost'].includes(run.phase)?null:checkpoint(run);try{localStorage.setItem(KEY,JSON.stringify(store));}catch{}}
const art={};for(const type of['steve','zombie','skeleton','creeper','villager','golem','spider','ravager'])art[type]=headData(type);
const iconPaths={
  tower:'<path fill="#aeb4a2" d="M3 21h18v3H3zM6 9h12v13H6z"/><path fill="#6e774e" d="M10 13h4v9h-4z"/><path fill="#bd9453" d="M2 5h20v4H2zM3 2h3v6H3zm7 0h4v6h-4zm8 0h3v6h-3z"/><path fill="#e3d7a1" d="M7 10h3v2H7z"/>',
  wall:'<path fill="#bd9256" d="M1 5h4v19H1zm9-3h4v22h-4zm9 3h4v19h-4zM2 9h20v4H2zm0 8h20v4H2z"/><path fill="#e3ba75" d="M1 5h2v18H1zM10 2h2v21h-2z"/>',
  farm:'<path fill="#b78743" d="M1 19h22v5H1z"/><path fill="#6d9e45" d="M5 7h2v13H5zm6-6h2v19h-2zm6 8h2v11h-2z"/><path fill="#e3c565" d="M3 4h6v6H3zm6-3h6v6H9zm6 4h6v7h-6z"/>',
  golem:'<path fill="#dadbc6" d="M6 1h12v9H6zM5 10h14v12H5zM1 11h4v13H1zm18 0h4v13h-4z"/><path fill="#5f7953" d="M7 11h3v9H7z"/><path fill="#8b5440" d="M8 4h2v2H8zm6 0h2v2h-2z"/><path fill="#b0a185" d="M11 5h3v5h-3z"/>',
  forge:'<path fill="#b8beb1" d="M2 5h20v6H2zM5 11h14v4H5zM9 14h6v7H9zM4 21h16v3H4z"/><path fill="#6c7c75" d="M2 5h20v2H2zM9 14h3v7H9z"/>',
  bow:'<path fill="#c3a16b" d="M8 1h5v4H8zm5 4h4v5h-4zm4 5h4v6h-4zm-4 6h4v5h-4zm-5 5h5v3H8z"/><path fill="#e7ead7" d="M7 2h2v21H7z"/><path fill="#94c8c1" d="M1 11h21v2H1zM19 9h4v6h-4z"/>',
  bell:'<path fill="#f0cc62" d="M8 2h8v4H8zM5 6h14v11H5zM2 17h20v4H2zM10 21h4v3h-4z"/><path fill="#fff0a1" d="M6 7h3v9H6z"/>'
};
function icon(type){return`<svg viewBox="0 0 24 26" class="svg-icon" aria-hidden="true">${iconPaths[type]||iconPaths.tower}</svg>`;}
$('hero-face').src=art.steve;$('golem-face').src=art.golem;$('bow-icon').innerHTML=icon('bow');document.querySelector('.bell-icon').innerHTML=icon('bell');document.querySelector('.bell-icon').style.transform='none';
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');toastTime=3.4;$('announcer').textContent=text;}
function selectSite(id){if(run.phase!=='day'||modal)return;selected=id;scene.selected=id;updateUI();}
function selectDistrict(id){if(modal)return;scene.district=id;scene.overview=false;selected=run.builds.find(b=>b.district===id&&b.unlock<=run.night)?.id||run.builds.find(b=>b.district===id)?.id||'northwatch';scene.selected=selected;scene.updateCamera(1);updateUI();}
function soundButton(){ $('sound').textContent=store.sound?'♪':'×';$('sound').setAttribute('aria-label',store.sound?'Mute sound':'Enable sound');}
function updateUI(){
  const night=run.phase==='night',day=run.phase==='day';document.body.classList.toggle('night',night||run.phase==='lost');document.body.classList.toggle('reduced-motion',store.reduced);scene.reduced=store.reduced;
  $('emeralds').textContent=run.emeralds;$('bell-fill').style.width=run.bell.hp/run.bell.max*100+'%';$('bell-fill').classList.toggle('low',run.bell.hp/run.bell.max<.35);$('village-hp').textContent=`${Math.round(run.bell.hp)} of ${run.bell.max} health`;
  $('hero-hearts').textContent='♥'.repeat(Math.ceil(run.hero.hp/run.hero.maxHp*5))+'♡'.repeat(5-Math.ceil(run.hero.hp/run.hero.maxHp*5));$('hero-hearts').setAttribute('aria-label',`${Math.round(run.hero.hp)} of ${run.hero.maxHp} health`);$('hero-label').textContent=run.hero.respawn?`RETURNING IN ${Math.ceil(run.hero.respawn)}s`:'STEVE';
  $('phase-icon').textContent=night?'☾':run.phase==='dawn'?'☀':'☀';$('phase-label').textContent=run.phase==='dawn'?'DAWN':`${night?'NIGHT':'DAY'} ${run.night} / ${TOTAL_NIGHTS}`;$('phase-tip').textContent=night?'Defend the bell · defeat every mob':run.phase==='dawn'?'The village lives to see another day':raidDetails(run.night).chapter;
  $('night-pips').innerHTML=Array.from({length:4},(_,i)=>`<i title="Nights ${i*5+1}–${i*5+5}" class="${i<Math.floor((run.night-1)/5)?'done':i===Math.floor((run.night-1)/5)?'current':''}"></i>`).join('');$('night-pips').setAttribute('aria-label',`Chapter ${Math.ceil(run.night/5)} of 4, night ${run.night} of ${TOTAL_NIGHTS}`);
  $('day-controls').hidden=!day;$('night-controls').hidden=!night;$('dawn-banner').hidden=run.phase!=='dawn';$('site-targets').hidden=!day;$('mob-targets').hidden=!night;$('district-nav').hidden=!day;
  $('map-view').setAttribute('aria-label',scene.overview?'Return to close view':'Show whole village map');$('map-view').classList.toggle('active',scene.overview);$('map-view').textContent=scene.overview?'⌖':'◇';
  $('hero-status').hidden=day&&scene.overview;$('map-summary').hidden=!scene.overview;$('build-card').hidden=scene.overview;
  $('map-summary-text').textContent=`${run.builds.filter(b=>b.level).length} of ${SITES.length} sites built · ${run.night<11?'South raids begin on night 11':'Four roads. One bell.'}`;
  for(const e of document.querySelectorAll('[data-district]'))e.setAttribute('aria-pressed',String(e.dataset.district===scene.district&&!scene.overview));
  $('repair-bell').hidden=!day||run.bell.hp>=run.bell.max;$('repair-bell').disabled=run.emeralds<3;
  const planned=run.builds.filter(b=>b.type==='golem'&&b.level).reduce((n,b)=>n+crewStatus(b).total,0);$('golem-status').hidden=!night||!planned;$('golem-summary').textContent=`GOLEMS ${run.guards.filter(g=>g.hp>0).length}/${planned} STANDING`;
  $('remaining').textContent=run.queue.length+run.enemies.filter(e=>e.hp>0).length;$('volley-status').textContent=run.hero.respawn?'Returning…':run.hero.volley>0?`${Math.ceil(run.hero.volley)}s`:'Ready';$('volley').disabled=!!run.hero.respawn||run.hero.volley>0;$('volley-fill').style.height=(run.hero.volley/10*100)+'%';
  const spec=raidInfo(run);$('raid-name').textContent=(spec.siege?'SIEGE · ':'')+spec.name;$('raid-name').classList.toggle('siege',spec.siege);$('raid-roads').textContent=spec.lanes.map(l=>l.short).join(' + ')+' road'+(spec.lanes.length>1?'s':'');if(raidUIKey!==String(run.night)){raidUIKey=String(run.night);$('raid-mobs').innerHTML=spec.types.map(t=>`<img alt="${MOBS[t].name}" src="${art[t==='armored'?'zombie':t]}">`).join('')+`<span>×${spec.count}</span>`;};$('start-night-text').textContent=`START NIGHT ${run.night}`;$('start-night').disabled=defenseCount(run)===0;document.querySelector('#start-night small').textContent=defenseCount(run)?spec.types.includes('ravager')?'Ravagers smash groups. Spread your defenses.':spec.types.includes('spider')?'Spiders climb walls. Cover the bell.':spec.types.includes('creeper')?'Creepers explode. Keep Steve moving.':spec.types.includes('skeleton')?'Skeleton arrows can be dodged.':'Protect the bell. Clear every mob.':'Place a defense before ringing the bell';
  const b=building(run,selected)||run.builds[0],def=BUILDINGS[b.type],dead=b.level&&b.hp<=0;$('site-name').textContent=b.name.toUpperCase()+(b.level?` · LEVEL ${b.level}`:'');$('build-name').textContent=def.name;$('build-health').hidden=!b.level;$('build-health').textContent=`${Math.ceil(b.hp)} / ${b.maxHp} HP`;$('build-icon').innerHTML=icon(b.type);const next=def.next[Math.min(MAX_LEVEL-1,b.level)];$('build-description').textContent=b.unlock>run.night?`Opens on day ${b.unlock}. Explore the other districts.`:b.level===MAX_LEVEL?`Max level · ${def.next[MAX_LEVEL-1]}`:dead?'Destroyed last night. Repair to use it again.':b.level?`Next: ${next}`:def.description;
  const yard=b.type==='golem'&&b.level>0;$('manage-golems').hidden=!yard;$('unselect').hidden=yard;if(yard){const squad=crewStatus(b);$('build-description').textContent=(b.hp<=0?'Yard ruined · squad inactive. ':`${squad.ready}/${squad.total} standing${squad.fallen?' · '+squad.fallen+' fallen':''}${squad.injured?' · '+squad.injured+' wounded':''}. `)+$('build-description').textContent;}if(b.exposed)$('build-description').textContent='Forward outpost: exposed to attacks. '+$('build-description').textContent;
  const cost=actionCost(b);$('build').textContent=b.unlock>run.night?`Opens day ${b.unlock}`:b.level>=MAX_LEVEL?'Fully upgraded':b.level>=levelCap(run.night)?`Next level · day ${run.night<6?6:11}`:`${b.level?'Upgrade':'Build'} · ${cost} ◆`;$('build').disabled=b.unlock>run.night||b.level>=levelCap(run.night)||run.emeralds<cost||!!dead;$('build').setAttribute('aria-label',b.unlock>run.night?`${def.name} opens on day ${b.unlock}`:b.level>=MAX_LEVEL?`${def.name} fully upgraded`:b.level>=levelCap(run.night)?`${def.name} next level opens on day ${run.night<6?6:11}`:`${b.level?'Upgrade':'Build'} ${def.name} for ${cost} emeralds`);$('repair').hidden=!b.level||b.hp>=b.maxHp;$('repair').textContent=`${yard?'Repair yard':'Repair'} · ${actionCost(b,'repair')}`;$('repair').disabled=run.emeralds<actionCost(b,'repair');$('sell').hidden=!b.level;$('sell').textContent=`Sell · +${salvageValue(b)}`;$('sell').setAttribute('aria-label',`Salvage ${def.name} for ${salvageValue(b)} emeralds. Damage and missing golems reduce the refund.`);soundButton();
}
function project({sites,mobs,guards=[]}){
  const parent=$('site-targets'),existing=new Map(Array.from(parent.children).map(e=>[e.dataset.site,e])),links=$('site-links');
  const gameTop=$('game').getBoundingClientRect().top,cardTop=$('day-controls').getBoundingClientRect().top-gameTop;
  const visible=run.phase!=='day'?[]:scene.overview?Object.entries(DISTRICTS).map(([id,d])=>({id:'zone:'+id,name:d.name,type:'district',p:scene.project(d.x,d.z,2),anchor:scene.project(d.x,d.z,.12),markerWidth:80,markerHeight:44,short:d.short})):sites.filter(b=>b.district===scene.district);
  const top=$('district-nav').getBoundingClientRect().bottom-gameTop+24;
  const positions=placeMarkers(visible,{width:scene.width,top,bottom:Math.max(top+46,cardTop-27)});links.hidden=run.phase!=='day';
  const activeLinks=new Set();
  for(const b of visible){
    let e=existing.get(b.id);existing.delete(b.id);
    if(!e){e=document.createElement('button');e.dataset.site=b.id;e.className='site-button';e.addEventListener('click',()=>{audio.unlock();if(b.id.startsWith('zone:'))selectDistrict(b.id.slice(5));else selectSite(b.id);});parent.append(e);}
    const zone=b.type==='district',locked=b.unlock>run.night,crew=b.type==='golem'&&b.level?crewStatus(b):null,state=`${b.level}/${b.hp>0}/${b.id===selected}/${locked}/${zone?run.night:''}/${crew?JSON.stringify(b.crew):''}`;
    if(e.dataset.state!==state){
      e.className=`site-button ${zone?'zone':b.level?'built':''} ${locked?'locked':''} ${crew?.cost?'needs-crew':''} ${b.level&&b.hp<=0?'ruin':''} ${b.id===selected?'selected':''}`;
      e.innerHTML=zone?`<strong>${b.short}</strong><small>${SITES.some(s=>s.district===b.id.slice(5)&&s.unlock<=run.night)?SITES.filter(s=>s.district===b.id.slice(5)&&s.unlock<=run.night).length+' sites open':'Opens day '+Math.min(...SITES.filter(s=>s.district===b.id.slice(5)).map(s=>s.unlock))}</small>`:icon(b.type)+`<b class="${b.level?'level':''}">${locked?'◷':b.level?b.hp<=0?'!':crew?.fallen?'!':crew?.injured?'+':'★'+b.level:BUILDINGS[b.type].cost[0]}</b>${b.level?'<span class="site-health"><i></i></span>':''}`;
      e.setAttribute('aria-label',zone?`Explore ${b.name}`:`${b.name}: ${BUILDINGS[b.type].name}, ${locked?'opens day '+b.unlock:b.level?'level '+b.level:'empty site, costs '+BUILDINGS[b.type].cost[0]+' emeralds'}`);if(crew)e.setAttribute('aria-label',e.getAttribute('aria-label')+`, squad ${crew.ready} standing, ${crew.fallen} fallen, ${crew.injured} wounded`);e.dataset.state=state;
    }
    if(b.level){const hp=e.querySelector('.site-health i');if(hp){hp.style.width=Math.max(0,b.hp/b.maxHp*100)+'%';hp.classList.toggle('low',b.hp/b.maxHp<.4);}}const p=positions.get(b.id);e.style.left=p.x+'px';e.style.top=p.y+'px';e.disabled=run.phase!=='day';
    let line=links.querySelector(`[data-link="${b.id}"]`);if(!line){line=document.createElement('i');line.dataset.link=b.id;links.append(line);}activeLinks.add(b.id);
    const dx=p.x-b.anchor.x,dy=p.y-b.anchor.y;line.style.cssText=`left:${b.anchor.x}px;top:${b.anchor.y}px;width:${Math.hypot(dx,dy)}px;transform:rotate(${Math.atan2(dy,dx)}rad)`;line.classList.toggle('selected',b.id===selected);
  }
  const hpParent=$('defense-health'),hpOld=new Map(Array.from(hpParent.children).map(e=>[e.dataset.health,e]));
  if(run.phase==='night')for(const b of sites)if(b.level&&b.hp<b.maxHp){let e=hpOld.get(b.id);hpOld.delete(b.id);if(!e){e=document.createElement('span');e.dataset.health=b.id;e.innerHTML='<i></i>';hpParent.append(e);}e.style.left=b.healthPoint.x+'px';e.style.top=b.healthPoint.y+'px';e.querySelector('i').style.width=Math.max(0,b.hp/b.maxHp*100)+'%';e.classList.toggle('low',b.hp/b.maxHp<.4);e.hidden=b.healthPoint.y<160||b.healthPoint.y>scene.height-120;}
  for(const e of hpOld.values())e.remove();
  for(const line of links.children)if(!activeLinks.has(line.dataset.link))line.remove();
  for(const e of existing.values())e.remove();const mp=$('mob-targets'),old=new Map(Array.from(mp.children).map(e=>[e.dataset.mob,e]));for(const mob of mobs){let e=old.get(mob.id);old.delete(mob.id);if(!e){e=document.createElement('button');e.dataset.mob=mob.id;e.className='mob-target'+(['armored','ravager'].includes(mob.type)?' boss':'');e.innerHTML='<span class="hp"><i></i></span>';e.addEventListener('click',()=>{if(!modal)focusMob(run,mob.id);});e.addEventListener('keydown',k=>{if(k.key==='Enter'){k.preventDefault();if(!modal)focusMob(run,mob.id);}});mp.append(e);}e.style.left=mob.p.x+'px';e.style.top=mob.p.y+'px';e.querySelector('i').style.width=Math.max(0,mob.hp/mob.maxHp*100)+'%';e.setAttribute('aria-label',`Approach ${MOBS[mob.type].name} on ${LANES[mob.lane].name}, ${Math.ceil(mob.hp)} health`);e.hidden=mob.p.y<145||mob.p.y>scene.height-100||mob.p.x<10||mob.p.x>scene.width-10;}
  const gp=$('guard-health'),previous=new Map(Array.from(gp.children).map(e=>[e.dataset.guard,e]));
  if(run.phase==='night')for(const g of guards){let e=previous.get(g.id);previous.delete(g.id);if(!e){e=document.createElement('span');e.dataset.guard=g.id;e.setAttribute('role','img');e.innerHTML='<b></b><i><em></em></i>';gp.append(e);}e.querySelector('b').textContent=g.hp>0?`GOLEM ${Math.ceil(g.hp)}`:'DOWN';e.querySelector('em').style.width=Math.max(0,g.hp/g.maxHp*100)+'%';e.classList.toggle('fallen',g.hp<=0);e.classList.toggle('low',g.hp>0&&g.hp/g.maxHp<.35);e.style.left=g.p.x+'px';e.style.top=g.p.y+'px';e.hidden=g.p.y<160||g.p.y>scene.height-120||g.p.x<20||g.p.x>scene.width-20;e.setAttribute('aria-label',`Iron golem ${g.slot+1} at ${building(run,g.yardId)?.name||'yard'}: ${g.hp>0?Math.ceil(g.hp)+' of '+g.maxHp+' health':'fallen'}`);}
  for(const e of previous.values())e.remove();
  for(const e of old.values())e.remove();
}
function openModal(kind,html){modal=kind;keys.clear();pointerInput={x:0,z:0};$('joystick').hidden=true;$('modal-layer').hidden=false;$('modal').className=kind;$('modal').innerHTML=html;$('modal').scrollTop=0;$('modal').focus();audio.stop();}
function closeModal(){modal=null;$('modal-layer').hidden=true;$('world').focus();}
const closeButton='<button class="modal-close" data-action="close" aria-label="Close dialog">×</button>';
function intro(){openModal('intro',`<div class="modal-eyebrow">A MINECRAFT-INSPIRED DEFENSE</div><h2>VILLAGE<br><span>LAST STAND</span></h2><p>A bigger village. Twenty long nights.<br>Build by day. Hold the line after dark.</p><div class="intro-face-row"><img src="${art.steve}" alt="Steve"><span class="vs">VS</span><img src="${art.zombie}" alt="Zombie"><img src="${art.skeleton}" alt="Skeleton"><img src="${art.creeper}" alt="Creeper"></div><div class="intro-steps"><div>BUILD<span>Spend emeralds</span></div><div>DEFEND<span>Move · auto-fire</span></div><div>SURVIVE<span>Protect the bell</span></div></div><button class="primary-action" data-action="enter">ENTER THE VILLAGE →</button><p class="help-footer">A small original defense game inspired by Minecraft and Thronefall.</p>`);}
function help(){openModal('help',`${closeButton}<div class="modal-eyebrow">THE VILLAGE HANDBOOK</div><h2>One bell.<br>Twenty nights to protect it.</h2><div class="help-row"><b>1</b><p><strong>Build before sunset</strong>Use the district tabs or ◇ map to explore, then tap a site and Build. Towers fire arrows; barricades block one road. Farms earn emeralds at dawn. A golem yard includes a guardian. Its wounds carry over; tap SQUAD to repair or recruit at dawn.</p></div><div class="help-row"><b>2</b><p><strong>Choose your plan</strong>Upgrade for more strength, repair damaged defenses or salvage buildings. Damage and missing golems reduce the refund. The next raid shows which roads and mobs are coming.</p></div><div class="help-row"><b>3</b><p><strong>You fight too</strong>Drag anywhere on the battlefield to move, or tap the ground to walk there. Steve shoots nearby mobs automatically. Volley hits several targets; it recharges in 10 seconds.</p></div><div class="help-row"><b>4</b><p><strong>Keep the bell standing</strong>Clear all 20 nights to win. New sites open on days 6, 11 and 16. Barricades stop ground mobs and low arrows. Towers lob arrows over them. Spiders climb barricades; explosions and ravagers can still splash nearby defenses. If Steve falls, he returns in five seconds. If the bell falls, retry from dawn and adjust your plan.</p></div><div class="settings-row"><span>Sound effects</span><button class="toggle" data-action="sound" role="switch" aria-checked="${store.sound}">${store.sound?'On':'Off'}</button></div><div class="settings-row"><span>Reduced motion</span><button class="toggle" data-action="motion" role="switch" aria-checked="${store.reduced}">${store.reduced?'On':'Off'}</button></div><p class="help-footer">Keyboard: WASD / arrows to move. Space for Volley at night. Tab to a mob and Enter to approach it. Escape pauses.<br><br>Your preparations are saved. Reloading during a battle returns to that night’s preparations.<br><br>Unofficial fan-made prototype. Original procedural models, textures and sound.</p><button class="primary-action" data-action="close">BACK TO THE VILLAGE</button>`);}
function squadMenu(){
 const b=building(run,selected);if(run.phase!=='day'||b?.type!=='golem'||!b.level)return;const max=golemMaxHP(b.level),stats=crewStatus(b),cost=crewServiceCost(b),ruined=b.hp<=0;
 const rows=b.crew.map((g,i)=>{const price=unitServiceCost(b,i),dead=g.hp<=0;return`<div class="crew-row ${dead?'fallen':''}"><img src="${art.golem}" alt="Iron golem"><div class="crew-details"><strong>Golem ${i+1}${dead?' · FALLEN':''}</strong><span>${Math.ceil(g.hp)} / ${max} HP</span><i class="crew-track"><em style="width:${g.hp/max*100}%"></em></i></div><button class="stone-button" data-action="service" data-slot="${i}" ${!price||price>run.emeralds||ruined?'disabled':''}>${!price?'Ready':dead?'Recruit · '+price+' ◆':'Repair · '+price+' ◆'}</button></div>`;}).join('');
 openModal('squad',`${closeButton}<div class="modal-eyebrow">${b.name.toUpperCase()} · LEVEL ${b.level}</div><h2>Iron golem squad</h2><p class="crew-intro">Damage carries into the next night. Fallen golems need paid recruits.</p><div class="crew-budget">${run.emeralds} emeralds · Yard ${Math.ceil(b.hp)} / ${b.maxHp} HP</div>${rows}<p class="crew-note">${ruined?'Repair the yard before servicing its squad.':'Choose individual golems or restore the whole squad.'}</p>${ruined?`<button class="secondary-action" data-action="repair-yard" ${actionCost(b,'repair')>run.emeralds?'disabled':''}>Repair yard · ${actionCost(b,'repair')} ◆</button>`:''}<button class="primary-action" data-action="service" data-slot="all" ${!cost||cost>run.emeralds||ruined?'disabled':''}>${cost?'RESTORE ALL · '+cost+' ◆':'ALL GOLEMS READY'}</button><button class="secondary-action" data-action="close">BACK TO THE YARD</button>`);
}
