  const y0=height(lo),y1=height(hi);if(Math.min(y0,y1)>rect.height+.0001)continue;
  let at=lo;if(y0>rect.height){let left=lo,right=hi;for(let i=0;i<15;i++){const mid=(left+right)/2;if(height(mid)>rect.height)left=mid;else right=mid;}at=right;}
  if(at<firstT){firstT=at;first=rect;}
 }
 return first?{...first,point:projectilePoint(a,firstT,target)}:null;
}
export function makeProjectile(from,target,source='hero'){
 return{x:from.x,z:from.z,y:source==='tower'?3.2:source==='skeleton'?1.3:1.65,tx:target.x,tz:target.z,ty:targetHeight(target),arc:source==='tower'?2.6:source==='volley'?3.3:.12,source,sourceId:from.id||null,targetId:target.id||'bell'};
}
export function aimBlock(r,from,target,source='hero',solids=coverBounds(r)){
 const hit=traceProjectile(r,makeProjectile(from,target,source),0,1,null,solids);
 return hit&&hit.id!==(target.id||'bell')?hit:null;
}
export function wallReach(from,wall){const b=wallBounds(wall);return Math.hypot(Math.max(0,Math.abs(from.x-b.x)-b.w/2),Math.max(0,Math.abs(from.z-b.z)-b.d/2));}

export const golemCount=level=>level>=5?3:level>=3?2:level>0?1:0;
export const golemMaxHP=level=>[0,180,220,255,295,340][level]||0;
export const recruitPrice=level=>[0,3,3,4,5,6][level]||0;
export function resizeCrew(b,oldLevel=0){
 const old=b.crew||[],max=golemMaxHP(b.level),oldMax=golemMaxHP(oldLevel)||1;
 b.crew=Array.from({length:golemCount(b.level)},(_,i)=>({hp:old[i]?old[i].hp>0?Math.min(max,Math.max(1,Math.round(old[i].hp/oldMax*max))):0:max}));
}
export function unitServiceCost(b,slot){
 if(b.type!=='golem'||!Number.isInteger(slot)||slot<0||slot>=golemCount(b.level))return Infinity;
 const hp=b.crew?.[slot]?.hp||0,max=golemMaxHP(b.level);
 return hp<=0?recruitPrice(b.level):Math.max(0,Math.ceil((max-hp)/90));
}
export function crewServiceCost(b,slot=null){
 if(slot!==null)return unitServiceCost(b,slot);
 return Array.from({length:golemCount(b.level)},(_,i)=>unitServiceCost(b,i)).reduce((n,c)=>n+c,0);
}
export function crewStatus(b){
 const total=golemCount(b.level),max=golemMaxHP(b.level);let ready=0,injured=0,hp=0;
 for(let i=0;i<total;i++){const life=b.crew?.[i]?.hp||0;hp+=life;if(life>0){ready++;if(life<max)injured++;}}
 return{total,ready,fallen:total-ready,injured,hp,maxHp:total*max,cost:crewServiceCost(b)};
}

// Keep every building's touch target distinct, even when a tall model covers a nearby plot.
export function placeMarkers(sites,{width,top,bottom}){
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const nodes=sites.map(s=>({id:s.id,w:s.markerWidth||50,h:s.markerHeight||40,x:clamp(s.p.x,(s.markerWidth||50)/2+4,width-(s.markerWidth||50)/2-4),y:clamp(s.p.y,top,bottom)}));
  for(let pass=0;pass<40;pass++){
    let moved=false;
    for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){
      const a=nodes[i],b=nodes[j],dx=b.x-a.x,dy=b.y-a.y,ox=(a.w+b.w)/2+6-Math.abs(dx),oy=(a.h+b.h)/2+6-Math.abs(dy);
      if(ox<=0||oy<=0)continue;
      moved=true;
      if(ox<oy){const d=(dx<0?-1:1)*(ox/2+.1);a.x-=d;b.x+=d;}
      else{const d=(dy<0?-1:1)*(oy/2+.1);a.y-=d;b.y+=d;}
      for(const n of[a,b]){n.x=clamp(n.x,n.w/2+4,width-n.w/2-4);n.y=clamp(n.y,top,bottom);}
    }
    if(!moved)break;
  }
  return new Map(nodes.map(n=>[n.id,n]));
}

import{build,actionCost,repairBell,levelCap,WAVES,focusMob,volley,serviceGolems,golemMaxHP}from'../core.mjs';
// QA-only player model uses legal purchases, walking input and Volley, with no resource bonuses.
export function prepareDay(r,policy=4){
 const n=r.night,early=policy>=3?[['northwatch','north-gate','wheat-field'],['eastwatch','east-gate'],['westwatch','west-gate','wheat-field'],['golem-yard','northwatch'],['westwatch','eastwatch']]:[['northwatch','north-gate','wheat-field'],['eastwatch','east-gate'],['westwatch','west-gate','golem-yard'],['northwatch'],['westwatch','eastwatch']];
 for(const id of early[n-1]||[])build(r,id);
 for(const b of r.builds.filter(b=>b.level&&b.hp<b.maxHp*.65).sort((a,b)=>(a.type==='wall')-(b.type==='wall')))build(r,b.id,'repair');
 while(r.bell.hp<170&&repairBell(r)){}
 const crewTasks=r.builds.filter(b=>b.type==='golem'&&b.hp>0).flatMap(b=>(b.crew||[]).map((g,slot)=>({b,g,slot}))).filter(t=>t.g.hp<golemMaxHP(t.b.level)*.7).sort((a,b)=>(a.g.hp===0)-(b.g.hp===0));
 for(const t of crewTasks)serviceGolems(r,t.b.id,t.slot);
 if(n<6)return;
 if(policy>=3&&n<13){const f=r.builds.filter(b=>b.type==='farm'&&b.unlock<=n&&b.level<3).sort((a,b)=>actionCost(a)-actionCost(b))[0];if(f)build(r,f.id);}
 for(let purchase=0;purchase<30;purchase++){
  const choices=[];
  for(const b of r.builds){
   if(b.unlock>n||b.level>=levelCap(n)||b.level&&b.hp<=0)continue;
   const cost=actionCost(b);if(cost>r.emeralds)continue;let value=0;
   if(b.type==='farm')value=(n<=13?1.7:.15)*(1+(policy%3)*.25)/(b.level+1);
   if(b.type==='tower')value=(b.district==='village'?2.7:1.35)*(b.level===2?1.5:b.level===4?1.6:1)/(1+b.level*.32);
   if(b.type==='golem')value=(b.id==='golem-yard'?2:1.25)*(b.level===2?1.6:b.level===4?1.5:1)/(1+b.level*.25);
   if(b.type==='forge')value=1.6/(1+b.level*.3);
   if(b.type==='wall')value=(b.level===0?.85:.45)/(1+b.level*.3);
   const pressure=WAVES[n-1].filter(w=>w.lane===b.lane).reduce((a,w)=>a+w.count,0);if(b.lane!==undefined)value*=.8+pressure/40;
   choices.push({b,value:value/cost**.2});
  }
  choices.sort((a,b)=>b.value-a.value);if(!choices.length||!build(r,choices[0].b.id).ok)break;
 }
}
export function createPilot(){return{night:0,timer:0,input:{x:0,z:0}};}
export function pilotInput(r,p,dt){
 if(r.phase!=='night')return{x:0,z:0};if(p.night!==r.night){p.night=r.night;p.timer=0;p.input={x:0,z:0};}volley(r);p.timer-=dt;
 if(p.timer<=0){p.timer=1.2;const e=r.enemies.filter(e=>e.hp>0).sort((a,b)=>Math.hypot(a.x,a.z-4.8)-Math.hypot(b.x,b.z-4.8))[0];
  if(e){focusMob(r,e.id);const dx=e.x-r.hero.x,dz=e.z-r.hero.z,d=Math.hypot(dx,dz);p.input=d>5?{x:dx/d,z:dz/d}:d<2.5&&d>.001?{x:-dx/d,z:-dz/d}:{x:0,z:0};}else p.input={x:0,z:0};
 }return p.input;
}
